import { Observable } from 'rxjs';
export function createIntersectionObserver(options, elements, zone) {
    return new Observable((obs) => {
        zone.runOutsideAngular(() => {
            const io = new IntersectionObserver((entries) => obs.next(entries), options);
            elements.forEach((element) => io.observe(element));
            return () => {
                elements.forEach((element) => io.unobserve(element));
                io.disconnect();
            };
        });
    });
}
