import { InjectionToken } from '@angular/core';
import { defaultOptions } from '../gallery.default';
export const GALLERY_OPTIONS = new InjectionToken('GALLERY_OPTIONS', {
    providedIn: 'root',
    factory: () => defaultOptions
});
export function provideGalleryOptions(options) {
    return {
        provide: GALLERY_OPTIONS,
        useValue: { ...defaultOptions, ...options }
    };
}
export const GALLERY_INITIAL_INDEX = new InjectionToken('GALLERY_INITIAL_INDEX');
