import { InjectionToken } from '@angular/core';
import { defaultOptions } from './a11y.default';
export const GALLERY_A11Y_OPTIONS = new InjectionToken('GALLERY_A11Y_OPTIONS', {
    providedIn: 'root',
    factory: () => defaultOptions
});
export function provideGalleryA11yOptions(options) {
    return {
        provide: GALLERY_A11Y_OPTIONS,
        useValue: options === false ? null : { ...defaultOptions, ...options }
    };
}
